INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11701, 'Nehemiah 13:8', 'Nehemiah', 13, 8, '&nbsp;زۀ سخت غصه شوم او د طوبياه ټول سامان مې بهر وغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11702, 'Nehemiah 13:9', 'Nehemiah', 13, 9, '&nbsp;ما حُکم ورکړو چې د کوټو د پاکوالى رسم دې ادا کړے شى او د خُدائ پاک د کور د سامان، د غلې نذرانې او خوشبوئى دې بيا واپس په خپل ځائ باندې کېښودلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11703, 'Nehemiah 13:10', 'Nehemiah', 13, 10, '&nbsp;ما ته دا پته هم ولګېده چې د خُدائ پاک د کور موسيقاران او نور ليويان د يروشلم نه تلى دى او خپلو پټو ته واپس شوى دى، دا ځکه چې خلقو هغوئ له دومره خوراک ورکولے نۀ شو چې ګزاره ورباندې کېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11704, 'Nehemiah 13:11', 'Nehemiah', 13, 11, '&nbsp;ما آفسران ورټل او ورته مې ووئيل چې د خُدائ پاک د کور خيال ولې نۀ دے ساتلے شوے. او ما ليويان او موسيقاران واپس د خُدائ پاک کور ته راوستل او بيا مې په کار لګيا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11705, 'Nehemiah 13:12', 'Nehemiah', 13, 12, '&nbsp;بيا ټول بنى اِسرائيليان يو ځل بيا شروع شول چې د خُدائ پاک د کور ګودامونو ته خپل د غلې لسمه حِصه، مے او د زيتُونو تېل راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11706, 'Nehemiah 13:13', 'Nehemiah', 13, 13, '&nbsp;ما دا سړى د ګودامونو مشران مقرر کړل: شلمياه، چې يو اِمام وو، صدوق، چې د شريعت يو عالِم وو، او فداياه ليوے. د متنياه نمسے او د زکور زوئ حنان د هغوئ مددګار وو. دا اعتبارى کسان وُو، او د هغوئ دا ذمه وارى وه چې په ليويانو باندې د سامان په تقسيمولو کښې د ايماندارۍ نه کار واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11707, 'Nehemiah 13:14', 'Nehemiah', 13, 14, '&nbsp;زما خُدايه پاکه، ياد ساته دا هر څۀ چې ما ستا د کور او د دې د عبادت دپاره کړى دى او دا مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11708, 'Nehemiah 13:15', 'Nehemiah', 13, 15, '&nbsp;په هغه وخت کښې ما وليدل چې په يهوداه کښې خلقو د سبت په ورځ د انګورو لنګرۍ استعمالوله. او نورو په خپلو خرونو باندې غله، مے، انګور، اينځر او نور څيزونه بار کول او يروشلم ته يې وړل، ما هغوئ له خبردارے ورکړو چې د سبت په ورځ دې هيڅ نۀ خرڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11709, 'Nehemiah 13:16', 'Nehemiah', 13, 16, '&nbsp;د صور ښار څۀ خلق په يروشلم کښې اوسېدل او هغوئ کبان او د هر قِسم سامان ښار ته د دې دپاره راوړو چې د سبت په ورځ يې زمونږ په خلقو باندې خرڅ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11710, 'Nehemiah 13:17', 'Nehemiah', 13, 17, '&nbsp;ما د يهوداه مشران ورټل او ورته مې ووئيل، ”تاسو خپل دې بد عمل ته وګورئ. تاسو د سبت د ورځې سپکاوے کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11711, 'Nehemiah 13:18', 'Nehemiah', 13, 18, '&nbsp;دا بلکل هم هغه کار دے چې خُدائ پاک پرې ستاسو پلار نيکۀ له سزا ورکړه چې کله هغۀ په ښار باندې تباهى راوسته. او تاسو نور زور هم کوئ چې د بنى اِسرائيلو په مُلک باندې د خُدائ پاک نور قهر هم نازل شى ځکه چې د سبت د ورځې سپکاوے کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11712, 'Nehemiah 13:19', 'Nehemiah', 13, 19, '&nbsp;نو ما حُکم ورکړو چې د هر سبت د شروع کېدو نه وړاندې د ښار دروازې په ماښامى کښې بندولے شى او د سبت د ورځې د ختمېدو نه وړاندې دې نۀ شى کولاولے. ما خپل يو څو سړى په دروازو باندې د دې دپاره ودرول چې دا خبره يقينى شى چې د سبت په ورځ به ښار ته هيڅ هم نۀ شى راوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11713, 'Nehemiah 13:20', 'Nehemiah', 13, 20, '&nbsp;يو يا دوه ځل سامان خرڅوونکو او سوداګرو د خالى شپه د ښار د دېوالونو نه بهر تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11714, 'Nehemiah 13:21', 'Nehemiah', 13, 21, '&nbsp;ما هغوئ له خبردارے ورکړو، ”تاسو د دې دېوال سره شپه ولې تېروئ کۀ تاسو بيا داسې وکړل، نو زۀ به تاسو خراب‌تُراب کړم.“ نو د دې نه پس هغوئ د سبت په ورځ بيا رانۀ غلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11715, 'Nehemiah 13:22', 'Nehemiah', 13, 22, '&nbsp;ما ليويانو له حُکم ورکړو چې خپل ځانونه پاک کړئ او لاړ شئ او د دروازو څوکيدارى وکړئ چې د سبت ورځ مقدسه پاتې شى. خُدايه پاکه، ما د دې دپاره هم ياد ساته او د خپلې لوئې مينې په وجه مې بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11716, 'Nehemiah 13:23', 'Nehemiah', 13, 23, '&nbsp;په هغه وخت کښې ما ته دا پته هم ولګېده چې څۀ يهودى سړو د اشدود، عمون او د موآب د ښځو سره ودونه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11717, 'Nehemiah 13:24', 'Nehemiah', 13, 24, '&nbsp;د هغوئ نيم اولاد د اشدود ژبه او يا څۀ بله ژبه وئيله او هغوئ زمونږ ژبه نۀ شوه وئيلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11718, 'Nehemiah 13:25', 'Nehemiah', 13, 25, '&nbsp;ما هغه سړو له خبردارے ورکړو، په هغوئ مې لعنت ووئيلو، ومې وهل او وېښتۀ مې ترې نه وويستل. بيا مې ترې نه د خُدائ پاک په نوم باندې دا قسم واخستو چې هغوئ او د هغوئ بچى به هيڅکله د پردى مُلک د خلقو سره ودونه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11719, 'Nehemiah 13:26', 'Nehemiah', 13, 26, '&nbsp;ما ورته ووئيل، ”سليمان د پردى مُلک د ښځو په وجه ګناه وکړه. هغه داسې سړے وو چې هغه د نورو قومونو د هر يو بادشاه نه لوئ وو. خُدائ پاک د هغۀ سره مينه کوله او هغه يې د بنى اِسرائيلو په ټول مُلک باندې بادشاه جوړ کړے وو، خو بيا هم هغه د پردى مُلک ښځو په ګناه باندې اخته کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11720, 'Nehemiah 13:27', 'Nehemiah', 13, 27, '&nbsp;نو مونږ به بيا د ګناهِ کبيره داسې عمل څنګه وکړُو چې د خُدائ پاک سره بې‌وفائى وکړُو او د پردى مُلک ښځو سره ودونه وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11721, 'Nehemiah 13:28', 'Nehemiah', 13, 28, '&nbsp;يويدع د مشر اِمام اِلياسب زوئ وو، خو د يويدع يو زوئ د بيت‌حورون د ښار د سنبلط د لور سره وادۀ وکړو، نو ما يويدع دې ته مجبور کړو چې يروشلم پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11722, 'Nehemiah 13:29', 'Nehemiah', 13, 29, '&nbsp;خُدايه پاکه، هغه راپه ياد کړه چې دې خلقو د اِمامت او د هغه لوظ سپکاوے څنګه وکړو چې کوم لوظ تا د اِمامانو او ليويانو سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11723, 'Nehemiah 13:30', 'Nehemiah', 13, 30, '&nbsp;نو ما خلق د پردى مُلک د هر يو څيز نه صفا کړل، ما د اِمامانو او ليويانو دپاره اصُول ځکه جوړ کړل چې هر يو کس خپله خپله ذمه وارى وپېژنى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11724, 'Nehemiah 13:31', 'Nehemiah', 13, 31, '&nbsp;ما د لرګو بندوبست وکړو چې هغه به د هغه نذرانو په سوزولو کښې استعمالېدل چې کومې نذرانې به په صحيح وخت راوړلے شوې، دا کار مې هم وکړو چې خلق د خپلې وړومبۍ غلې او خپلې وړومبۍ پخې شوې مېوې راوړى. خُدايه پاکه، دا هر څۀ مۀ هېروه او را ياد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11725, 'Esther 1:3', 'Esther', 1, 3, '&nbsp;د هغۀ د بادشاهۍ په درېم کال هغۀ خپلو ټولو آفسرانو او وزيرانو له يوه لويه مېلمستيا وکړه. د فارس او د مادى فوجى آفسران هم موجود وُو او داسې د صُوبو حکمرانان او عزتمند سړى هم موجود وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11726, 'Esther 1:4', 'Esther', 1, 4, '&nbsp;په پوره شپږو مياشتو کښې هغۀ د شان او شوکت او عظمت سره د شاهى دربار د ټول دولت نمائش وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11727, 'Esther 1:5', 'Esther', 1, 5, '&nbsp;د هغې نه پس، بادشاه ټولو خلقو ته د سوسه په مرکزى ښار کښې يوه لويه مېلمستيا وکړه، چې مالداره او غريبانان په کښې يو شان شامل وُو. دا مېلمستيا پوره يوه هفته جارى وه او دا د شاهى محل په باغونو کښې شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11728, 'Esther 1:6', 'Esther', 1, 6, '&nbsp;دربار د آسمانى رنګ او د سپين رنګ د مالوچو جوړو شوو پړدو باندې ښائسته کړے شوے وو، د سنګِ مرمرو په ستنو باندې د سپينو زرو د کَړو سره د کاسنى رنګ د ښې لټې د مزو سره تړلے شوې وې. د سرو زرو او سپينو زرو کټُونه په دربار کښې اېښودے شوى وُو، د دربار فرش د سپين سنګِ مرمر، سور قيمتى کاڼى، د ځلېدونکې ملغلرو او د آسمانى رنګ د فيروزو نه جوړ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11729, 'Esther 1:7', 'Esther', 1, 7, '&nbsp;د سرو زرو په پيالو کښې شراب ورکول چې هره يوه پيالۍ به د بلې په شان نۀ وه او بادشاه به په شاهى ميو کښې د سخاوت نه کار اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11730, 'Esther 1:8', 'Esther', 1, 8, '&nbsp;د شرابو په څښلو کښې حد مقرر نۀ وو، بادشاه د محل نوکرانو له حُکم ورکړے وو چې د هر چا زړۀ چې څومره غواړى نو هغه څښلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11731, 'Esther 1:9', 'Esther', 1, 9, '&nbsp;هم په دې دوران کښې، د شاهى محل دننه مَلِکه وشتى د ښځو دپاره مېلمستيا کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11732, 'Esther 1:10', 'Esther', 1, 10, '&nbsp;د خپلې مېلمستيا په اوومه ورځ باندې بادشاه په نشه کښې وو او ښۀ په سور کښې وو، نو هغۀ اووۀ خصيان راوغوښتل کوم چې د هغۀ ذاتى خِدمتګاران وُو، مهُومان، بِزتا، خربونا، بِګتا، ابګتا، زتار او کرکس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11733, 'Esther 1:11', 'Esther', 1, 11, '&nbsp;بادشاه هغوئ ته حُکم وکړو چې مَلِکه وشتى دننه راولئ چې شاهى تاج يې په سر وى. مَلِکه يوه ښائسته ښځه وه او بادشاه غوښتل چې د هغې حُسن آفسرانو او خپلو ټولو مېلمنو ته وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11734, 'Esther 1:12', 'Esther', 1, 12, '&nbsp;خو کله چې خِدمتګارانو مَلِکه وشتى ته د بادشاه د حُکم په حقله ووئيل، نو هغې د راتلو نه اِنکار وکړو. نو په دې باندې بادشاه د غصې نه تک سور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11735, 'Esther 1:13', 'Esther', 1, 13, '&nbsp;نو دا د بادشاهانو رِواج وو چې د قانون او حُکمونو د سوالونو په حقله يې د ماهِرانو رايې معلوموله، نو هغۀ خپل هغه مشيران راوغوښتل، چې هغوئ ته به پته وه چې څۀ کول په کار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11736, 'Esther 1:14', 'Esther', 1, 14, '&nbsp;کوم مشيران به چې بادشاه له ورتلل نو هغه کارشينا، شتر، ادماتا، ترسيس، مرس، مرسنا او مموکان وُو، دا اووۀ د فارس او مادى هغه آفسران وُو چې په بادشاهۍ کښې يې د ټولو نه اوچتې مرتبې لرلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11737, 'Esther 1:15', 'Esther', 1, 15, '&nbsp;بادشاه دې سړو ته ووئيل، ”ما، يعنې اخسويرس بادشاه، خپل خصيان د يو حُکم سره مَلِکه وشتى ته ولېږل او هغې د دې حُکم د منلو نه اِنکار وکړو. قانون د دې په حقله څۀ وائى چې مونږ د هغې سره څۀ وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11738, 'Esther 1:16', 'Esther', 1, 16, '&nbsp;نو مموکان بادشاه او د هغۀ آفسرانو ته ووئيل، ”مَلِکه وشتى نۀ صِرف د بادشاه بې‌عزتى کړې ده بلکې هغې د آفسرانو او د ټول قوم بې‌عزتى يې کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11739, 'Esther 1:17', 'Esther', 1, 17, '&nbsp;د بادشاهۍ هره يوه ښځه چې خبر شى چې مَلِکه څۀ کړى دى نو هغه به خپل خاوند ته سپک کتل شروع کړى. هغوئ به وائى چې اخسويرس بادشاه مَلِکه وشتى له حُکم ورکړو چې راشه، خو هغې اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11740, 'Esther 1:18', 'Esther', 1, 18, '&nbsp;نن چې د فارس او مادى د شاهى آفسرانو ښځې د مَلِکه د دې کار نه خبر شى نو هغوئ به هم د خپلو خاوندانو سره هم دغه شان د بې‌عزتۍ سلوک کوى او داسې به دا معامله ډېره خرابه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11741, 'Esther 1:19', 'Esther', 1, 19, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو شاهى فرمان جارى کړه چې وشتى دې بيا هيڅکله د بادشاه په مخکښې نۀ حاضريږى. دا حُکم وکړه چې دا د فارس او مادى په قانون کښې وليکلے شى، نو داسې به هيڅوک هم دا نۀ شى بدلولے. بيا د هغې د مَلِکه عهده د هغې نه زياتې حقدارې ښځې له ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11742, 'Esther 1:20', 'Esther', 1, 20, '&nbsp;کله چې ستا د دې فرمان پته په دې لويه بادشاهۍ کښې ولګى، نو هره ښځه به د خپل خاوند ښۀ عزت کوى، کۀ هغه مالداره وى او کۀ غريب وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11743, 'Esther 1:21', 'Esther', 1, 21, '&nbsp;د بادشاه او د هغۀ د وزيرانو دا خبره خوښه شوه او مموکان چې کومه مشوره ورکړې وه نو بادشاه هم هغه شان وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11744, 'Esther 1:22', 'Esther', 1, 22, '&nbsp;هغۀ هرې شاهى صُوبې ته د هغه صُوبې په ژبه او رسم‌الخط کښې يو پېغام ولېږلو، چې په کښې وئيلے شوى وُو چې هر يو خاوند به د خپل کور مشرى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11745, 'Esther 2:1', 'Esther', 2, 1, '&nbsp;وروستو، کله چې د بادشاه غصه سړه شوې وه، نو هغۀ بيا هم د وشتى د عمل او د هغې خِلاف د فرمان په حقله سوچ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11746, 'Esther 2:2', 'Esther', 2, 2, '&nbsp;نو د بادشاه خادِمانو هغۀ له مشوره ورکړه، ”مونږ به ستا دپاره يو څو ښائسته ناوادۀ شوې پېغلې ولټوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11747, 'Esther 2:3', 'Esther', 2, 3, '&nbsp;تۀ د بادشاهۍ په هره يوه صُوبه کښې آفسران مقرر کړه او هغوئ له حُکم ورکړه چې هغوئ ټولې ښائسته پېغلې په مرکزى ښار سوسه کښې ستا د زناناؤ ځائ ته راولى. هيجا څوک چې د بادشاه د زناناؤ مشر دے او خصى دے هغه به د هغوئ خيال ساتى او د هغوئ د سنګار بندوبست به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11748, 'Esther 2:4', 'Esther', 2, 4, '&nbsp;نو چې کومه پېغله ستا ډېره خوښه شى نو هغه بوځه او د وشتى په ځائ يې خپله مَلِکه جوړه کړه.“ نو بادشاه ووئيل چې دا يوه ښۀ مشوره ده، نو هغۀ په دې خبره باندې عمل وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11749, 'Esther 2:5', 'Esther', 2, 5, '&nbsp;په هغه وخت کښې هلته په سوسه کښې يو يهودى اوسېدو چې نوم يې مردکى وو او هغه د يائير زوئ وو، هغه د بنيامين د قبيلې وو او د قيس او سِمعى د اولاد نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11750, 'Esther 2:6', 'Esther', 2, 6, '&nbsp;کله چې د بابل بادشاه نبوکدنضر د يهوداه بادشاه يهوياکين د يروشلم نه بابل مُلک ته بوتلو، د قېديانو يوه ډله هم ورسره وه، او مردکى هم په هغوئ کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11751, 'Esther 2:7', 'Esther', 2, 7, '&nbsp;د هغۀ يوه د ترۀ لور اِستَر وه، چې د هغې عبرانے نوم هدسا وو، هغه يوه ښائسته پېغله وه او ښۀ کړۀ‌وړۀ يې وُو. د هغې د مور او پلار د مرګ نه پس، مردکى هغه اخستې وه او د خپلې لور په توګه يې راوستې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11752, 'Esther 2:8', 'Esther', 2, 8, '&nbsp;کله چې بادشاه خپل نوے فرمان جارى کړو او ډيرې پېغلې سوسه ته راوستلے شوې، نو اِستَر هم په هغوئ کښې وه. هغه هم په شاهى محل کښې هيجا ته حواله شوه، کوم چې د بادشاه د زناناؤ د ځائ مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11753, 'Esther 2:9', 'Esther', 2, 9, '&nbsp;د هيجا اِستَر خوښه شوه او هغه پرې مِهربانه شو. هغۀ سمدستى د هغې د سنګار او د خاص خوراک بندوبست وکړو. هغۀ ورله د بادشاه د زناناؤ په ځائ کښې د ټولو نه ښۀ ځائ ورکړو او د هغې د خِدمت دپاره يې اووۀ پېغلې مقررې کړې چې د شاهى محل نه په خصوصى توګه خوښې کړې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11754, 'Esther 2:10', 'Esther', 2, 10, '&nbsp;نو د مردکى د نصيحت په وجه، اِستَر خپل قوم او خاندان پټ ساتلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11755, 'Esther 2:11', 'Esther', 2, 11, '&nbsp;مردکى به هره ورځ د بادشاه د ښځو د ځائ نه بهر د دې دپاره ګرځېدو راګرځېدو چې د دې پته ولګوى چې اِستَر څنګه ده او په هغې باندې څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11756, 'Esther 2:12', 'Esther', 2, 12, '&nbsp;د ښځو سنګار يو کال جارى وو، د خوشبودار چيړ د تېلو مالش شپږ مياشتې او د خاص خوشبو او تېلو مالش نورې شپږ مياشتې جارى وو. د هغې نه پس، هره يوه پېغله به وار په وار اخسويرس بادشاه له بوتلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11757, 'Esther 2:13', 'Esther', 2, 13, '&nbsp;کله چې هغه به د بادشاه د ښځو ځائ نه محل ته تله، نو چې هغې به څنګه جامې غوښتلې نو هغه به يې اغوستې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11758, 'Esther 2:14', 'Esther', 2, 14, '&nbsp;داسې به وشو چې کله به هغه هلته د ماښام تلله او په ورپسې سحر به هغه د بادشاه د ښځو يو بل ځائ ته بوتلے شوه او شعشجز خصى د هغې خيال ساتلو، چې کوم د بادشاه د وينځو مشر وو. هغه به تر هغې پورې بيا بادشاه له نۀ ورتله ترڅو چې بادشاه به يې ښۀ خوشحاله کړے نۀ وو او بادشاه به هغه په نوم رابللې نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11759, 'Esther 2:15', 'Esther', 2, 15, '&nbsp;نو هغه وخت راغلو چې اِستَر بادشاه له لاړه شى. اِستَر د ابى‌خېل لور او د مردکى د ترۀ لور وه، چې مردکى هغه د خپلې لور په توګه اخستې وه. کله چې د هغې وار راغلو، نو هغې هم هغه جامې اغوستې وې د کومو مشوره چې د بادشاه د ښځو د کور مشر هيجا نومې خصى له ورکړې وه، اِستَر چې چا هم ليدله نو د هغۀ به خوښېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11760, 'Esther 2:16', 'Esther', 2, 16, '&nbsp;نو د اخسويرس د بادشاهۍ په اوؤم کال، په لسمه مياشت يعنې د طيبت په مياشت کښې، اِستَر شاهى محل ته اخسويرس بادشاه ته راوستلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11761, 'Esther 2:17', 'Esther', 2, 17, '&nbsp;اِستَر د بادشاه د نورو ټولو پېغلو نه زياته خوښه شوه، نو ځکه يې هغې له زړۀ او مينه ورکړه. هغۀ شاهى تاج ور په سر کړو او د وشتى په ځائ يې مَلِکه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11762, 'Esther 2:18', 'Esther', 2, 18, '&nbsp;بيا بادشاه د اِستَر د درناوى دپاره يوه لويه مېلمستيا وکړه او خپلو ټولو آفسرانو او وزيرانو له يې دعوت ورکړو. هغۀ د ټولې بادشاهۍ دپاره په هغه ورځ د چُهټۍ اِعلان وکړو او هر چا له يې قيمتى تُحفې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11763, 'Esther 2:19', 'Esther', 2, 19, '&nbsp;په دې دوران کښې بادشاه مردکى د محل آفسر مقرر کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11764, 'Esther 2:20', 'Esther', 2, 20, '&nbsp;اِستَر تر اوسه پورې خپل قوم او خاندان پټ ساتلے وو، لکه څنګه چې مردکى ورته وئيلى وُو. او څنګه چې هغې په ماشوموالى کښې د مردکى خبره منله اوس يې هم منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11765, 'Esther 2:21', 'Esther', 2, 21, '&nbsp;په هغه وخت کښې چې مردکى په محل کښې دفتر ونيولو، بِګتان او ترش، د محل دوه هغه خصيانو کومو چې د اخسويرس بادشاه کوټو ته د ننوتلو د ځائ څوکيدارى کوله، هغوئ د بادشاه خِلاف شول او د هغۀ د وژلو منصوبه يې جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11766, 'Esther 2:22', 'Esther', 2, 22, '&nbsp;خو مردکى د دې منصوبې نه خبر شو او دا خبر يې مَلِکه اِستَر ته ورسولو. بيا هغې بادشاه ته ووئيل چې مردکى زۀ د دې نه خبر کړې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11767, 'Esther 2:23', 'Esther', 2, 23, '&nbsp;کله چې د منصوبې تفتيش وشو او پته ولګېده چې هغه خبر رښتيا وو، نو هغوئ په دار باندې ځوړند کړے شول. بادشاه حُکم وکړو چې دا واقعه دې د شاهى تاريخ په کِتاب کښې وليکلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11768, 'Esther 3:1', 'Esther', 3, 1, '&nbsp;څۀ موده وروستو اخسويرس بادشاه همان نومې سړى له ترقى ورکړه او د وزيرانو مشر يې جوړ کړو. همان د اجاج د قوم همداتا زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11769, 'Esther 3:2', 'Esther', 3, 2, '&nbsp;بادشاه خپلو ټولو آفسرانو له حُکم ورکړو چې همان ته د عزت نه ټيټېږئ، خو مردکى يې عزت نۀ کولو او نۀ ورته ټيټېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11770, 'Esther 3:3', 'Esther', 3, 3, '&nbsp;نورو شاهى آفسرانو د هغۀ نه تپوس وکړو چې، ”تۀ د بادشاه د حُکم نافرمانى ولې کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11771, 'Esther 3:4', 'Esther', 3, 4, '&nbsp;هغوئ به هره ورځ ورته وئيل، خو هغۀ به ورته غوږ نۀ نيولو. هغۀ به وئيل، ”زۀ همان ته نۀ شم ټيټېدلے ځکه چې زۀ يهودى يم.“ نو هغوئ همان د دې نه خبر کړو، هغوئ غوښتل چې وګورى چې هغه به د مردکى دا رويه برداشت کړى کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11772, 'Esther 3:5', 'Esther', 3, 5, '&nbsp;کله چې همان ته پته ولګېده چې مردکے هغۀ ته د عزت نه نۀ ټيټيږى نو همان سخت غصه شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11773, 'Esther 3:6', 'Esther', 3, 6, '&nbsp;او کله چې خبر شو چې مردکے يهودى دے، نو همان دا فېصله وکړه چې هغه به نۀ صرف مردکى له سزا ورکوى بلکې هغۀ دا منصوبه هم جوړه کړه چې د فارس په بادشاهۍ کښې هر يو يهودى ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11774, 'Esther 3:7', 'Esther', 3, 7, '&nbsp;د اخسويرس بادشاه د حکومت په دولسم کال، په وړومبۍ مياشت يعنې د نسان په مياشت، همان حُکم وکړو چې پوريم يعنې پچه دې واچولے شى چې دا معلومه کړى چې د دې منصوبې دپاره صحيح مياشت کومه يوه ده. نو د دولسمې مياشتې يعنې د ادر مياشتې ديارلسمه ورځ خوښه کړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11775, 'Esther 3:8', 'Esther', 3, 8, '&nbsp;نو همان د بادشاه په مخکښې حاضر شو او ورته يې ووئيل، ”ستا په ټوله بادشاهۍ کښې د خلقو يو قِسم نسل خور دے او دا په هره صُوبه کښې موندلے شى. هغوئ داسې رِواجونه کوى چې هغه د نورو ټولو خلقو په شان نۀ دى. د دې نه علاوه، هغوئ د بادشاهۍ قانون هم نۀ منى، نو دا ستا دپاره د فائدې خبره نۀ ده چې هغوئ برداشت کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11776, 'Esther 3:9', 'Esther', 3, 9, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو يو فرمان جارى کړه چې هغوئ دې ووژلے شى. کۀ تا داسې وکړل، نو زۀ به د بادشاهۍ د اِنتظام دپاره د درې لاکه او څلوېښتو زرو کېلو نه زيات سپين زر په شاهى خزانه کښې کېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11777, 'Esther 3:10', 'Esther', 3, 10, '&nbsp;بادشاه خپله هغه ګوتمه وويستله، چې هغه به په سرکارى فرمان باندې د مهر لګولو دپاره استعمالېدله او دا يې د يهوديانو دشمن د همداتا زوئ همان له ورکړه چې دے د اجاج د اولاد نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11778, 'Esther 3:11', 'Esther', 3, 11, '&nbsp;بادشاه همان ته ووئيل، ”سپين زر ځان سره کړه او د خلقو سره هم هغسې وکړه څنګه چې دې زړۀ غواړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11779, 'Esther 3:12', 'Esther', 3, 12, '&nbsp;نو د وړومبۍ مياشتې په ديارلسمه ورځ باندې همان د بادشاه منشيان راوغوښتل او يو فرمان يې جارى کړو چې د هرې صُوبې په ژبه او رسم‌الخط کښې دې د دې ترجمه وشى او ټولو حکمرانانو، حاکِمانو او آفسرانو ته دې ولېږلے شى. دا فرمان د اخسويرس بادشاه په نوم جارى شو او د هغۀ د ګوتمې مهر ورباندې لګېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11780, 'Esther 3:13', 'Esther', 3, 13, '&nbsp;پېغام رسونکو دا فرمان د بادشاهۍ هرې صُوبې ته يوړو. په دې کښې دا خبرې ليکلے شوې وې چې صِرف په هغه ورځ يعنې د ادر مياشتې په ديارلسمه ورځ باندې دې ټول يهوديان، ځوانان، بوډاګان، ښځې او ماشومان ووژلے شى. هغوئ دې د بې‌رحمۍ سره حلال کړے شى او چې هغوئ څۀ لرى نو هغه ترې نه واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11781, 'Esther 3:14', 'Esther', 3, 14, '&nbsp;د دې فرمان د خبرو نه د هرې صُوبې خلق ځکه خبرول په کار وُو، چې کله هغه ورځ راشى نو چې هر يو کس ورته تيار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11782, 'Esther 3:15', 'Esther', 3, 15, '&nbsp;د بادشاه د حُکم په مطابق هغه فرمان د سوسه په مرکزى ښار کښې خلقو ته ورسولے شو او پېغام رسونکو دا خبر نورو صُوبو ته يوړو. په کوم وخت کښې چې د سوسه ښار په ګډوډۍ کښې اچولے شو نو بادشاه او همان شرابو څښلو ته ناست وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11783, 'Esther 4:1', 'Esther', 4, 1, '&nbsp;کله چې مردکے د هغه هر څۀ نه خبر شو چې څۀ شوى وُو، نو هغۀ د خفګان نه خپلې جامې وشلولې. بيا هغۀ د ټاټ جامې واغوستلې، سر يې په ايرو پټ کړو، په ښار کښې روان شو او تر هغې پورې يې په چغو چغو او بد بد ژړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11784, 'Esther 4:2', 'Esther', 4, 2, '&nbsp;چې د محل دروازې ته ورسېدو. هغه دننه ځکه لا نۀ ړو چې د ټاټ په جامو کښې دننه د تلو اجازت نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11785, 'Esther 4:3', 'Esther', 4, 3, '&nbsp;په ټولو صُوبو کښې، چرته هم چې د بادشاه د فرمان پته لګېدلې وه، نو هلته يهوديانو په چغو چغو ژړل. هغوئ روژه ونيوله، ژړا او وير يې کولو او ډېرو کسانو د ټاټ جامې اغوستې وې او سر يې په ايرو پټ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11786, 'Esther 4:4', 'Esther', 4, 4, '&nbsp;کله چې د اِستَر ښځو خِدمتګارانو او خصيانو اِستَر ته ووئيل چې مردکى څۀ کول، نو هغه سخته پرېشانه شوه. نو هغې مردکى له څۀ جامې ولېږلې چې د ټاټ جامو په ځائ يې واغوندى، خو هغۀ به نۀ اخستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11787, 'Esther 4:5', 'Esther', 4, 5, '&nbsp;بيا هغې هتاک راوغوښتلو، هغه يو خصى وو چې بادشاه د هغې نوکر کړے وو او هغې هغۀ ته وفرمائيل چې مردکى له لاړ شه او د دې پته ولګوه چې څۀ مسئله ده چې هغه دومره غمژن دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11788, 'Esther 4:6', 'Esther', 4, 6, '&nbsp;هتاک د محل د دروازې مخامخ د ښار چوک ته مردکى له لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11789, 'Esther 4:7', 'Esther', 4, 7, '&nbsp;مردکى ورته ټوله قيصه بيان کړه او دا يې هم ورته ووئيل چې کۀ ټول يهوديان ووژلے شول نو همان په شاهى خزانه کښې د څومره پېسو د کېښودو وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11790, 'Esther 4:8', 'Esther', 4, 8, '&nbsp;هغۀ هتاک له د هغه فرمان يو نقل ورکړو چې کوم په سوسه کښې جارى شوے وو، چې په هغې کښې د يهوديانو د تباهۍ حُکم وو. مردکى هتاک ته ووئيل چې دا اِستَر له يوسه او اِستَر د حالاتو نه خبر کړه او هغې ته ووايه چې لاړه شى او بادشاه ته دا سوال زارى وکړى چې د هغې په خلقو رحم وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11791, 'Esther 4:9', 'Esther', 4, 9, '&nbsp;نو هتاک د مردکى د پېغام سره اِستَر له راواپس شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11792, 'Esther 4:10', 'Esther', 4, 10, '&nbsp;او اِستَر هغۀ له دا پېغام ورکړو چې مردکى له يې يوسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11793, 'Esther 4:11', 'Esther', 4, 11, '&nbsp;”کۀ هر څوک، سړے يا ښځه، د دعوت نه بغېر دننه د بادشاه دربار ته لاړ شى، نو هغه کس به وژلے شى، دا يو قانون دے، د بادشاه د مشيرانو نه واخله په صُوبو کښې د خلقو پورې هر يو کس د دې نه خبر دے. د دې قانون نه د بچ کېدو صِرف يوه لار ده، کۀ بادشاه يو کس ته خپله د سرو زرو امسا اوږده کړى، نو د هغه کس ژوند به بچ شى. خو د دې يوه مياشت وشوه چې بادشاه زۀ راغوښتے نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11794, 'Esther 4:12', 'Esther', 4, 12, '&nbsp;کله چې مردکى ته د اِستَر پېغام مِلاو شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11795, 'Esther 4:13', 'Esther', 4, 13, '&nbsp;نو هغۀ اِستَر ته دا پېغام ولېږلو، ”داسې مۀ وايه چې په ټولو يهوديانو کښې به صرف تۀ بچ شې ولې چې تۀ په شاهى محل کښې يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11796, 'Esther 4:14', 'Esther', 4, 14, '&nbsp;کۀ تۀ په داسې وخت کښې هم خاموشه پاتې شوې، نو د يو بل ځائ نه به د يهوديانو دپاره مدد راشى او هغوئ به بچ شى، خو تۀ به مړه شې او ستا د پلار خاندان به ختم شى. د دې نه څوک خبر دى کېدے شى چې تۀ هم د دې وخت دپاره مَلِکه جوړه شوې يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11797, 'Esther 4:15', 'Esther', 4, 15, '&nbsp;اِستَر مردکى له دا جواب ولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11798, 'Esther 4:16', 'Esther', 4, 16, '&nbsp;”لاړ شه او په سوسه کښې ټول يهوديان په يو ځائ راغونډ کړه، روژه ونيسئ او زما دپاره دُعا وکړئ. درې ورځې او درې شپې هيڅ خوراک څښاک مۀ کوئ. زۀ او زما خِدمتګارې به هم ستاسو په شان روژه ونيسو. د هغې نه پس به بيا زۀ بادشاه له لاړه شم، اګر چې دا د قانون خِلاف ورزى ده. خو کۀ د داسې کولو په وجه زۀ مرم، نو مړه دې شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11799, 'Esther 4:17', 'Esther', 4, 17, '&nbsp;نو بيا مردکى لاړو او هغه هر څۀ يې وکړل چې اِستَر ورته وئيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11800, 'Esther 5:1', 'Esther', 5, 1, '&nbsp;د روژې په درېمه ورځ اِستَر شاهى لِباس واغوستلو، لاړه او د محل په دنننى دربار کښې د تخت کوټې ته مخامخ ودرېدله. بادشاه دننه وو او د محل دروازې ته مخامخ په شاهى تخت ناست وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');